    $x=wc_get_order(35436); $o['sim'][35436]=array('pries'=>array('st'=>$x->get_status(),'total'=>$x->get_total(),'griz'=>(string)$x->get_meta('_ps_siunta_grizta'))); $x->update_meta_data('_ps_siunta_grizta',wp_json_encode(array('quattro'=>array('nr'=>'V07267E1000778','t'=>'grįžta siuntėjui (sim)','e'=>'','d'=>'','kada'=>$now)))); $x->save();
