      $o['uzs'][$id]=array('st'=>$x->get_status(),'total'=>$x->get_total(),'sh'=>$sh,'it'=>$it,'griz'=>(string)$x->get_meta('_ps_siunta_grizta'),'graz'=>(string)$x->get_meta('_ps_grazinti_rankomis'),'own_16727'=>get_post_meta(16727,'_own_stock_qty',true),'stock_16727'=>get_post_meta(16727,'_stock',true)); }
