    foreach(array(35434,35436) as $id){ $r=wp_remote_get(admin_url('admin-ajax.php?action=ps_dl_skydelis&id='.$id.'&n='.$n),array('cookies'=>$cs,'timeout'=>60,'sslverify'=>false)); $d=(json_decode((string)wp_remote_retrieve_body($r),true)['data']??array()); $o['sk'][$id]=array('kl'=>$d['klausimas']??null,'kur'=>$d['kur']??null,'suma'=>$d['suma']??null); }
