    foreach(array(35434,35436) as $id){ if(preg_match('/<div class="dl-kortele eil" data-id="'.$id.'"(.*?)<\/div>\s*(?=<div class="dl-kortele|<\/)/su',$h,$m)){ $k=$m[1]; $o['kortele'][$id]=array('sumos'=>preg_match('/<p class="dl-sumos">(.*?)<\/p>/su',$k,$s)?trim(preg_replace('/\s+/',' ',wp_strip_all_tags(html_entity_decode($s[1])))):'NĖRA','tekstas'=>preg_match('/<\/h2><p>(.*?)<\/p>/su',$k,$s)?trim(wp_strip_all_tags($s[1])):'','mygtukai'=>preg_match_all('/<a class="v[^"]*"[^>]*>(.*?)<\/a>/su',$k,$mm)?array_map('wp_strip_all_tags',$mm[1]):array(),'dialog_ats'=>preg_match('/v=grizta_atsaukti[^>]*data-d="([^"]*)"/su',$k,$dd)?mb_substr(html_entity_decode($dd[1]),0,400):'NĖRA'); } else { $o['kortele'][$id]='KORTELĖS NĖRA'; } }
    wp_set_current_user(0);
    $exp2=time()+1800; $tok2=WP_Session_Tokens::get_instance($uid)->create($exp2);
    $o['cookies']=array(array('name'=>SECURE_AUTH_COOKIE,'value'=>wp_generate_auth_cookie($uid,$exp2,'secure_auth',$tok2)),array('name'=>AUTH_COOKIE,'value'=>wp_generate_auth_cookie($uid,$exp2,'auth',$tok2)),array('name'=>LOGGED_IN_COOKIE,'value'=>wp_generate_auth_cookie($uid,$exp2,'logged_in',$tok2)));
    $o['shots']=array(array('n'=>'s1616_e7_klausimai_sumos','u'=>admin_url('admin.php?page=ps-desk&eile=klausimai'),'w'=>1400,'full'=>true,'eval'=>"({sumos:[...document.querySelectorAll('.dl-kortele .dl-sumos')].map(function(x){return x.closest('.dl-kortele').getAttribute('data-id')+': '+x.innerText.replace(/\\s+/g,' ');})})"));
  }
  }catch(Throwable $e){ $o['FATAL']=$e->getMessage().' @'.$e->getFile().':'.$e->getLine(); }
  $J($o);
